function validate([values]) {
  if (!Array.isArray(values) || values.length < 2 || values.length > 50000) return 'values needs 2 to 5 * 10^4 spots.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value is a whole number from 1 to 1000.';
  return null;
}

