function maxScoreSightseeingPair(values) {
  // Score every pair i < j directly.
  let best = null;
  for (let i = 0; i < values.length; i++)
    for (let j = i + 1; j < values.length; j++) {
      const score = values[i] + values[j] + i - j;
      if (best === null || score > best) best = score;
    }
  return best;
}

